refentry.refsect1:
&reftitle.description;
intjson_last_error
Restituisce l'ultimo errore (se presente) verificatosi durante l'ultima validazione/codifica/decodifica JSON che non ha specificato JSON_THROW_ON_ERROR.

  &reftitle.examples;



    Esempio di json_last_error


<?php
// Una stringa JSON valida
$json[] = '{"Organization": "PHP Documentation Team"}';

// Una stringa JSON non valida che causerà un errore di
// sintassi, in questo caso abbiamo usato ' invece di " per le virgolette
$json[] = "{'Organization': 'PHP Documentation Team'}";


foreach ($json as $string) {
    echo 'Decoding: ' . $string;
    json_decode($string);

    switch (json_last_error()) {
        case JSON_ERROR_NONE:
            echo ' - No errors';
        break;
        case JSON_ERROR_DEPTH:
            echo ' - Maximum stack depth exceeded';
        break;
        case JSON_ERROR_STATE_MISMATCH:
            echo ' - Underflow or the modes mismatch';
        break;
        case JSON_ERROR_CTRL_CHAR:
            echo ' - Unexpected control character found';
        break;
        case JSON_ERROR_SYNTAX:
            echo ' - Syntax error, malformed JSON';
        break;
        case JSON_ERROR_UTF8:
            echo ' - Malformed UTF-8 characters, possibly incorrectly encoded';
        break;
        default:
            echo ' - Unknown error';
        break;
    }

    echo PHP_EOL;
}
?>


    &example.outputs;


Decoding: {"Organization": "PHP Documentation Team"} - No errors
Decoding: {'Organization': 'PHP Documentation Team'} - Syntax error, malformed JSON







    json_last_error con json_encode


<?php
// Una sequenza UTF8 non valida
$text = "\xB1\x31";

$json  = json_encode($text);
$error = json_last_error();

var_dump($json, $error === JSON_ERROR_UTF8);
?>


    &example.outputs;


string(4) "null"
bool(true)







    json_last_error e JSON_THROW_ON_ERROR


<?php
// Una sequenza UTF8 non valida che causa JSON_ERROR_UTF8
json_encode("\xB1\x31");

// Quanto segue non causa un errore JSON
json_encode('okay', JSON_THROW_ON_ERROR);

// Lo stato globale di errore non è stato modificato dal precedente json_encode()
var_dump(json_last_error() === JSON_ERROR_UTF8);
?>


    &example.outputs;


bool(true)
